import{z as i,x as A,o as e,c as B,q as n,j as t,D as r,d as o,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Granger 因果","description":"","frontmatter":{"title":"Granger 因果","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/granger-causality.md","filePath":"quant/granger-causality.md","lastUpdated":1791413859000}'),p={name:"quant/granger-causality.md"};function d(g,a,m,h,_,c){const E=A("Mermaid");return e(),B("div",null,[a[2]||(a[2]=n('<h1 id="granger-因果" tabindex="-1">Granger 因果 <a class="header-anchor" href="#granger-因果" aria-label="Permalink to &quot;Granger 因果&quot;">​</a></h1><div class="epigraph"><p>若 $x$ 的过去在 $y$ 自己的过去之外还能改善 $y$ 的预测，就说 $x$ Granger 引起 $y$；这是均方预测的可检验陈述，不是结构方程里的箭头。</p><footer>—— Granger, Investigating Causal Relations by Econometric Models and Cross-spectral Methods, Econometrica, 1969</footer></div><p><a href="/quant/var-irf">VAR 与脉冲响应</a> 已经把系统写好。IRF 还差一个识别假设才能谈「冲击」。Granger 在同一套滞后上问更窄的问题：块外生——\\(\\Phi\\) 的某些块是否为零。本课缺口：把「预测帮助」从结构因果、从同期相关、从非同步交易里拆出来。下一课状态空间处理的是潜变量与测量，不是把 Granger 箭头升级成结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二元时，在 \\(y_t\\) 对 \\(y_{t-1},\\ldots,y_{t-p}\\) 的回归里加入 \\(x\\) 的滞后，联合显著性就是 Granger 检验（Wald）。多元则是 VAR 里 \\(x\\) 块对 \\(y\\) 方程的零约束。原假设：\\(x\\) 的过去不改善 \\(y\\) 的线性预测。问题是水平扭曲——单位根、滞后选错、异方差——以及<strong>解释过度</strong>：显著并不等于 \\(x\\) 是 \\(y\\) 的原因，更不等于可干预。</p><p>Sims 指出：Granger 与「严格外生」相关但不等价；存在期望的反馈可以让真实结构因果在 Granger 意义上双向。金融里还有第三种假箭头：A 股对美股「Granger 引起」只因开盘时差，信息已在隔夜期货里。</p><p><span class="marginnote">「Granger 因果」可以翻译成「预测加分」：如果把 \\(x\\) 的历史成绩单附在 \\(y\\) 自己的历史后面，能让 \\(y\\) 明天的预测更准，就说 \\(x\\) Granger 引起 \\(y\\)。它考的是预测考试，不追问「按下去 \\(x\\)，\\(y\\) 会不会动」——那是干预问题，考试不考。</span></p><h3 id="检验技术" tabindex="-1">检验技术 <a class="header-anchor" href="#检验技术" aria-label="Permalink to &quot;检验技术&quot;">​</a></h3><p>水平近单位根时，普通 Wald 非标准，Toda–Yamamoto 用 \\(p+d_{\\max}\\) 滞后再检验前 \\(p\\) 个，水平可以标准。异方差用稳健 Wald；GARCH 残差用自助。滞后 \\(p\\) 用信息准则，但检验对 \\(p\\) 敏感：太短漏动态，太长功效低。应报告 \\(p\\) 的范围。</p><p><span class="marginnote">同期 Granger（瞬时因果）看 \\(\\Sigma_\\varepsilon\\) 的非对角，那是相关不是预测。把它写成「瞬时因果」容易与结构冲击混淆。应单独报残差相关，不要塞进 Granger 一词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>线性。</strong> VAR-Wald 或单方程 HAC Wald。出报告：F/Wald、稳健版本、\\(p\\) 的选择。滚动窗口看稳定性——全样本显著常由一段危机贡献，接后课 Chow。</p><p><strong>非线性、分位。</strong> 均值 Granger 为零，尾部仍可有（Hong 等）。上一课的分位工具可以做分位 Granger，多重 \\(\\tau\\) 须控制。本课默认线性均值，声明若做尾部。</p><p><strong>高频。</strong> 用成交时钟或领先滞后回归，而不是日历分钟的 Granger。日历网格的 previous-tick 会制造假领先，见 <a href="/quant/irregular-sampling">不等间隔采样</a>。Hasbrouck 信息份额是微观结构里更对口的「谁先动」，对象是随机游走分解，不是 VAR-Wald。</p><h3 id="与-irf、gmm-的关系" tabindex="-1">与 IRF、GMM 的关系 <a class="header-anchor" href="#与-irf、gmm-的关系" aria-label="Permalink to &quot;与 IRF、GMM 的关系&quot;">​</a></h3><p>Granger 零约束成立时，正交化 IRF 里 \\(x\\) 冲击对 \\(y\\) 的路径仍可非零（经同期相关与其他变量）。反之，IRF 看起来为零，滞后块仍可显著（符号在地平线上抵消）。两套输出都要。GMM 的矩外生是另一层：\\(E[u_t z_{t-1}]=0\\) 可以是有效工具，不必是 Granger 因果的叙述。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预测改善来自 \\(x\\) 含有关于 \\(y\\) 未来的信息，在线性张成里尚未被 \\(y\\) 自己的滞后张出。共同因子 \\(f_t\\) 驱动两者、且 \\(x\\) 对 \\(f\\) 反应更快，会出现 \\(x\\to y\\) 的 Granger，而结构是 \\(f\\) 引起两者。机制是<strong>信息时点</strong>，不是干预。这就是为什么宏观里要用外生工具或符号约束去做 IRF，而不是停在 Granger。</p>',18)),(e(),t(s,null,{default:r(()=>[l(E,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%85%B1%E5%90%8C%E5%9B%A0%E5%AD%90%20f_t%22%5D%20--%3E%7C%22%E5%8F%8D%E5%BA%94%E5%BF%AB%22%7C%20X%5B%22x_t%20%E5%85%88%E5%8A%A8%22%5D%0A%20%20F%20--%3E%7C%22%E5%8F%8D%E5%BA%94%E6%85%A2%22%7C%20Y%5B%22y_t%20%E5%90%8E%E5%8A%A8%22%5D%0A%20%20X%20--%3E%7C%22x%20%E7%9A%84%E8%BF%87%E5%8E%BB%E5%90%AB%20f%20%E7%9A%84%E4%BF%A1%E6%81%AF%22%7C%20P%5B%22%E5%9B%9E%E5%BD%92%20y%3A%20%E5%8A%A0%E5%85%A5%20x%20%E6%BB%9E%E5%90%8E%E6%98%BE%E8%91%97%22%5D%0A%20%20Y%20--%3E%20P%0A%20%20P%20--%3E%20Q%5B%22%E7%BB%9F%E8%AE%A1%E4%B8%8A%3A%20x%20Granger%20%E5%BC%95%E8%B5%B7%20y%22%5D%0A%20%20P%20-.-%3E%7C%22%E7%BB%93%E6%9E%84%E4%B8%8A%E5%85%B6%E5%AE%9E%E6%98%AF%22%7C%20TR%5B%22f%20%E5%BC%95%E8%B5%B7%20x%20%E4%B8%8E%20y%EF%BC%8Cx%20%E5%8F%AA%E6%98%AF%E4%BF%A1%E4%BD%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">直觉类比：闪电先亮、雷声后响。在「雷声对闪电的回归」里加进闪电的滞后确实能改善雷声预测，但闪电并不是雷声的原因——两者共同由放电产生，只是传播速度不同。共同因子驱动下的 Granger 箭头，画的正是这种「信使领先」。</span></p><p>非同步：收盘价对不上同一瞬间的信息集，\\(x\\) 的「过去」可能已含 \\(y\\) 的未来。修正是对齐时钟或用重叠调整，不是加大 \\(p\\)。</p><p><span class="marginnote">样本外 Granger：样本内显著、样本外均方无改善，则更像过拟合。应把检验放到滚动预测，与后课 QLIKE 的样本外精神一致。</span></p><h3 id="政策语言" tabindex="-1">政策语言 <a class="header-anchor" href="#政策语言" aria-label="Permalink to &quot;政策语言&quot;">​</a></h3><p>「订单流 Granger 引起收益」在微观结构里往往是定义的一部分（价格对交易的冲击）。把它写成因果政策（限制交易会降低波动）需要结构模型（Kyle、Hasbrouck VAR 的识别）。本课停在检验的合法对象：预测。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(k\\) 大时两两 Granger 是多重检验。长记忆下显著性会虚高。缺失、隔夜、午休要把样本切段，跨段 Granger 无意义。</p><p>工程：报告稳健 Wald、\\(p\\) 敏感性、滚动；高频改信息份额或 HY 滞后。不要用 Granger 替代 <a href="/quant/iv-finance">IV</a> 的排除。不要在新闻标题里把 Granger 写成「导致」。下一课把不可观测状态写进滤波，预测将变成状态的条件均值。</p><p><span class="marginnote">数字实例：\\(p=5\\)、两个变量时，每个方程要估 10 个滞后系数加常数；若日度样本只有两年（约 500 个观测）还勉强，但换成分钟数据按日切段后每段不到 400 个点，系数一多、自由度一紧，Wald 统计量就容易虚高——这就是「\\(p\\) 太长功效低」的具体代价。</span></p>',9)),(e(),t(s,null,{default:r(()=>[l(E,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20TD%0A%20%20VAR%5B%22VAR%20%E6%BB%9E%E5%90%8E%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20W%5B%22Wald%3A%20x%20%E6%BB%9E%E5%90%8E%E5%9D%97%E6%98%AF%E5%90%A6%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20W%20--%3E%20PRED%5B%22%E7%BB%93%E8%AE%BA%3A%20%E7%BA%BF%E6%80%A7%E9%A2%84%E6%B5%8B%E6%98%AF%E5%90%A6%E6%94%B9%E5%96%84%22%5D%0A%20%20PRED%20-.-%3E%7C%22%E4%B8%8D%E6%98%AF%22%7C%20STR%5B%22%E7%BB%93%E6%9E%84%E5%9B%A0%E6%9E%9C%20%2F%20%E5%8F%AF%E5%B9%B2%E9%A2%84%22%5D%0A%20%20IRF%5B%22IRF%20%E8%BF%98%E9%9C%80%E8%AF%86%E5%88%AB%22%5D%20--%3E%20DIFF%5B%22%E4%B8%8E%20Granger%20%E5%8F%AF%E4%B8%8D%E4%B8%80%E8%87%B4%22%5D%0A%20%20W%20--%3E%20DIFF%0A%20%20NS%5B%22%E9%9D%9E%E5%90%8C%E6%AD%A5%20%2F%20%E5%85%B1%E5%90%8C%E5%9B%A0%E5%AD%90%22%5D%20--%3E%20FAKE%5B%22%E5%81%87%20Granger%20%E7%AE%AD%E5%A4%B4%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Granger 因果是「滞后是否改善均方预测」的 Wald 检验，依附 VAR 的块外生。</li><li>单位根用 Toda–Yamamoto；异方差用稳健或自助；滞后阶要报告敏感性。</li><li>共同因子与非同步会制造假箭头；高频应改时钟与信息份额。</li><li>与 IRF 分工：一个不需正交化、一个需要；两者都不能单独承担结构政策。</li><li>出处：Granger, <em>Econometrica</em>, 1969；Toda and Yamamoto, <em>Journal of Econometrics</em>, 1995；宏观讨论见 Sims。</li></ul>',2))])}const f=i(p,[["render",d]]);export{F as __pageData,f as default};
